1	import { createSeaMap, isNavigable, type SeaMapDefinition } from "@pirate-sea-race/content";
2	import { describe, expect, it } from "vitest";
3	import {
4	  createEncounterConfig,
5	  createEncounterState,
6	  duelMarkers,
7	  hashState,
8	  stepEncounters,
9	  tileCentre,
10	  tileOf,
11	  type DuelReport,
12	  type EncounterConfig,
13	  type EncounterEvent,
14	  type EncounterPlayerInput,
15	  type EncounterState,
16	  type EncounterStateOptions,
17	} from "./index.js";
18	
19	/**
20	 * A 40 × 24 test sea: land at column 20, rows 3–6, a shoal at (20, 10), and a dock in each corner (ids 0–3:
21	 * (1,1), (38,1), (1,22), (38,22)).
22	 */
23	const ROWS = Array.from({ length: 24 }, (_, row) => {
24	  const tiles = Array.from({ length: 40 }, () => ".");
25	  if (row >= 3 && row <= 6) tiles[20] = "#";
26	  if (row === 10) tiles[20] = "%";
27	  if (row === 1 || row === 22) tiles[1] = tiles[38] = "D";
28	  return tiles.join("");
29	});
30	const map: SeaMapDefinition = createSeaMap({ name: "test", widthTiles: 40, heightTiles: 24, rows: ROWS, islands: [], spawnSlots: [], hub: { tileX: 20, tileY: 12 } });
31	const config = createEncounterConfig({ map });
32	const TILE = map.subUnitsPerTile;
33	const at = (tileX: number, tileY: number) => tileCentre(map, { tileX, tileY });
34	
35	function ship(id: string, tileX: number, tileY: number, heading = 0, extra: Partial<EncounterPlayerInput> = {}): EncounterPlayerInput {
36	  return { id, mode: "ship", ...at(tileX, tileY), heading, connected: true, attack: false, ready: false, protectionEndedBy: null, ...extra };
37	}
38	
39	interface TickOptions {
40	  readonly press?: readonly string[];
41	  readonly reports?: readonly DuelReport[];
42	  readonly matchOver?: boolean;
43	}
44	
45	/** A scripted match: players persist between ticks; presses last one tick. */
46	class World {
47	  state: EncounterState;
48	  readonly players = new Map<string, EncounterPlayerInput>();
49	  readonly log: EncounterEvent[] = [];
50	
51	  constructor(
52	    players: readonly EncounterPlayerInput[],
53	    options: EncounterStateOptions = {},
54	    readonly cfg: EncounterConfig = config,
55	  ) {
56	    this.state = createEncounterState(cfg, options);
57	    for (const player of players) this.players.set(player.id, player);
58	  }
59	
60	  get tick(): number {
61	    return this.state.tick;
62	  }
63	
64	  set(id: string, change: Partial<EncounterPlayerInput>): void {
65	    this.players.set(id, { ...this.players.get(id)!, ...change });
66	  }
67	
68	  remove(id: string): void {
69	    this.players.delete(id);
70	  }
71	
72	  step(options: TickOptions = {}): EncounterEvent[] {
73	    const press = new Set(options.press ?? []);
74	    const players = [...this.players.values()].map((player) => ({ ...player, attack: press.has(player.id) }));
75	    const result = stepEncounters(this.cfg, this.state, { tick: this.state.tick + 1, players, reports: options.reports ?? [], matchOver: options.matchOver ?? false });
76	    this.state = result.state;
77	    this.log.push(...result.events);
78	    // Reported protection ends are one-tick signals.
79	    for (const player of this.players.values()) if (player.protectionEndedBy !== null) this.set(player.id, { protectionEndedBy: null });
80	    return [...result.events];
81	  }
82	
83	  /** Steps until `tick` has been processed, returning every event on the way. */
84	  runTo(tick: number): EncounterEvent[] {
85	    const events: EncounterEvent[] = [];
86	    while (this.state.tick < tick) events.push(...this.step());
87	    return events;
88	  }
89	
90	  record(id: string) {
91	    return this.state.players.find((player) => player.id === id);
92	  }
93	}
94	
95	const kinds = (events: readonly EncounterEvent[]) => events.map((event) => event.kind);
96	const started = (events: readonly EncounterEvent[]) => events.filter((event) => event.kind === "attempt-started");
97	const ofKind = <K extends EncounterEvent["kind"]>(events: readonly EncounterEvent[], kind: K) =>
98	  events.filter((event): event is Extract<EncounterEvent, { kind: K }> => event.kind === kind);
99	
100	/** Presses once on tick 1 and runs to the landing tick (21). */
101	function grapple(world: World, attacker: string): EncounterEvent[] {
102	  const events = world.step({ press: [attacker] });
103	  return [...events, ...world.runTo(1 + config.modes.ship.windupTicks)];
104	}
105	
106	describe("starting an attempt (§6)", () => {
107	  it("picks the nearest eligible ship in range, line of sight and the front cone, and locks the aim toward it", () => {
108	    const world = new World([ship("a", 5, 12), ship("far", 9, 12), ship("near", 8, 12), ship("behind", 3, 12)]);
109	    const events = world.step({ press: ["a"] });
110	    expect(events).toEqual([{ kind: "attempt-started", tick: 1, attackerId: "a", defenderId: "near", mode: "ship", aim: 0, landTick: 21 }]);
111	    expect(world.state.attempts).toEqual([{ attackerId: "a", defenderId: "near", mode: "ship", aim: 0, startTick: 1, landTick: 21 }]);
112	  });
113	
114	  it("takes a target at the ±8 cone's edge and not one just outside it", () => {
115	    // (2, -2) tiles is heading 56, 8 off heading 0; (1, -2) is heading 53, 11 off.
116	    const edge = new World([ship("a", 5, 12), ship("edge", 7, 10), ship("ahead", 9, 12)]);
117	    expect(started(edge.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "edge", aim: 56 });
118	    const outside = new World([ship("a", 5, 12), ship("steep", 6, 10), ship("ahead", 9, 12)]);
119	    expect(started(outside.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "ahead", aim: 0 });
120	  });
121	
122	  it("reaches exactly the grapple range and not one sub-unit further", () => {
123	    const world = new World([ship("a", 5, 12), { ...ship("b", 11, 12), x: at(5, 12).x + 6 * TILE + 1 }]);
124	    expect(world.step({ press: ["a"] })).toEqual([]);
125	    world.set("b", { x: at(5, 12).x + 6 * TILE });
126	    expect(started(world.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "b" });
127	  });
128	
129	  it("passes over a nearer ship behind land, but not one behind a shoal", () => {
130	    // Land at column 20 rows 3–6; a shoal at (20, 10).
131	    const land = new World([ship("a", 17, 5), ship("hidden", 22, 5), ship("seen", 17, 9, 16)]);
132	    land.set("a", { heading: 0 });
133	    expect(land.step({ press: ["a"] })).toEqual([]);
134	    const shoal = new World([ship("a", 17, 10), ship("reef", 22, 10)]);
135	    expect(started(shoal.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "reef" });
136	  });
137	
138	  it("breaks a distance tie to the lower id, wherever the players stand and whatever order they arrive in", () => {
139	    for (const [first, second] of [
140	      ["zed", "bob"],
141	      ["bob", "zed"],
142	    ] as const) {
143	      const world = new World([ship(first, 8, 11), ship("a", 5, 12), ship(second, 8, 13)]);
144	      expect(started(world.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "bob" });
145	    }
146	  });
147	
148	  it("starts nothing and costs nothing when a press finds no target", () => {
149	    const world = new World([ship("a", 5, 12), ship("b", 12, 12)], { spawnProtected: ["a"] });
150	    expect(world.step({ press: ["a"] })).toEqual([]);
151	    expect(world.state.attempts).toEqual([]);
152	    // No cooldown and the attacker keeps their protection.
153	    expect(world.record("a")).toEqual({ id: "a", protection: { source: "spawn", endTick: 900 }, cooldownEndTick: 0, respawn: null });
154	    world.set("b", { ...at(10, 12) });
155	    expect(kinds(world.step({ press: ["a"] }))).toEqual(["protection-ended", "attempt-started"]);
156	  });
157	
158	  it("ignores a press while the player's own attempt winds up", () => {
159	    const world = new World([ship("a", 5, 12), ship("b", 7, 12), ship("c", 6, 12)]);
160	    world.step({ press: ["a"] });
161	    expect(world.step({ press: ["a"] })).toEqual([]);
162	    expect(world.state.attempts).toHaveLength(1);
163	  });
164	});
165	
166	describe("escape (§6)", () => {
167	  it("lands a hit on a defender who stayed", () => {
168	    const world = new World([ship("a", 5, 12), ship("b", 8, 12)]);
169	    const events = grapple(world, "a");
170	    expect(ofKind(events, "duel-reserved")).toEqual([
171	      { kind: "duel-reserved", tick: 21, duelId: "duel:21:1:a:b", mode: "ship", players: ["a", "b"], x: Math.floor((at(5, 12).x + at(8, 12).x) / 2), y: at(5, 12).y },
172	    ]);
173	    expect(world.state.attempts).toEqual([]);
174	  });
175	
176	  it("misses a defender who left the range, costing the attacker the cooldown", () => {
177	    const world = new World([ship("a", 5, 12), ship("b", 8, 12)]);
178	    world.step({ press: ["a"] });
179	    world.runTo(20);
180	    world.set("b", at(12, 12));
181	    expect(world.step()).toEqual([{ kind: "attempt-missed", tick: 21, attackerId: "a", defenderId: "b", reason: "out-of-range", cooldownEndTick: 141 }]);
182	  });
183	
184	  it("misses a defender who left the aim, even within range", () => {
185	    const world = new World([ship("a", 5, 12), ship("b", 8, 12)]);
186	    world.step({ press: ["a"] });
187	    world.runTo(20);
188	    // (3, -3) tiles: heading 56, 8 off the locked aim of 0.
189	    world.set("b", at(8, 9));
190	    expect(ofKind(world.step(), "attempt-missed")[0]).toMatchObject({ reason: "out-of-aim" });
191	  });
192	
193	  it("misses a defender who slipped behind land", () => {
194	    const world = new World([ship("a", 16, 7), ship("b", 21, 7)]);
195	    world.step({ press: ["a"] });
196	    world.runTo(20);
197	    // (5, -1) tiles: heading 62, inside the aim, but the line crosses the land at (20, 6).
198	    world.set("b", at(21, 6));
199	    expect(ofKind(world.step(), "attempt-missed")[0]).toMatchObject({ reason: "no-line-of-sight" });
200	  });
201	
202	  it("follows the aim while the defender stays inside it: moving within ±4 headings is no escape", () => {
203	    const world = new World([ship("a", 5, 12), ship("b", 9, 12)]);
204	    world.step({ press: ["a"] });
205	    world.runTo(20);
206	    world.set("b", at(9, 11)); // (4, -1): heading 60, 4 off.
207	    expect(kinds(world.step())).toEqual(["duel-reserved"]);
208	  });
209	});
210	
211	describe("cooldown on a miss only", () => {
212	  it("refuses presses until the six seconds are over, then starts again", () => {
213	    const world = new World([ship("a", 5, 12), ship("b", 8, 12)]);
214	    world.step({ press: ["a"] });
215	    world.runTo(20);
216	    world.set("b", at(12, 12));
217	    world.step();
218	    world.set("b", at(8, 12));
219	    for (let tick = 22; tick < 141; tick++) expect(world.step({ press: ["a"] })).toEqual([]);
220	    expect(world.record("a")?.cooldownEndTick).toBe(141);
221	    expect(started(world.step({ press: ["a"] }))).toHaveLength(1);
222	    expect(world.tick).toBe(141);
223	    // A record with nothing left to remember is dropped.
224	    expect(world.record("a")).toBeUndefined();
225	  });
226	
227	  it("costs nothing for a preempted hit or a cancelled attempt", () => {
228	    // b's attempt on c loses to a's closer hit on b, so b is reserved: a preemption.
229	    const world = new World([ship("a", 5, 12), ship("b", 7, 12), ship("c", 10, 12), ship("d", 5, 20), ship("e", 7, 20)]);
230	    world.step({ press: ["a", "b", "d"] });
231	    world.set("d", { connected: false });
232	    const events = world.runTo(21);
233	    expect(ofKind(events, "attempt-preempted")).toEqual([{ kind: "attempt-preempted", tick: 21, attackerId: "b", defenderId: "c", reason: "conflict" }]);
234	    expect(ofKind(events, "attempt-cancelled")).toEqual([{ kind: "attempt-cancelled", tick: 2, attackerId: "d", defenderId: "e", reason: "attacker-ineligible" }]);
235	    expect(world.record("d")).toBeUndefined();
236	    world.set("d", { connected: true });
237	    expect(started(world.step({ press: ["d"] }))).toHaveLength(1);
238	  });
239	});
240	
241	describe("eligibility at the start and at landing", () => {
242	  it("never targets a protected defender, and a protected attacker's start ends their own protection", () => {
243	    const world = new World([ship("a", 5, 12), ship("b", 7, 12), ship("c", 9, 12)], { spawnProtected: ["a", "b"] });
244	    const events = world.step({ press: ["a"] });
245	    expect(events).toEqual([
246	      { kind: "protection-ended", tick: 1, playerId: "a", reason: "attack" },
247	      { kind: "attempt-started", tick: 1, attackerId: "a", defenderId: "c", mode: "ship", aim: 0, landTick: 21 },
248	    ]);
249	    expect(world.record("b")?.protection).toEqual({ source: "spawn", endTick: 900 });
250	  });
251	
252	  it("targets a protected player who presses on the same tick only from the next tick, whatever the input order", () => {
253	    for (const order of [["a", "b"], ["b", "a"]]) {
254	      const players = { a: ship("a", 5, 12), b: ship("b", 7, 12, 32) };
255	      const world = new World(order.map((id) => players[id as "a" | "b"]), { spawnProtected: ["b"] });
256	      const events = world.step({ press: ["a", "b"] });
257	      expect(started(events).map((event) => [event.attackerId, event.defenderId])).toEqual([["b", "a"]]);
258	    }
259	  });
260	
261	  it("misses a defender reserved by someone else's hit during the windup, and never targets a reserved one", () => {
262	    const world2 = new World([ship("a", 3, 12), ship("b", 7, 12), ship("c", 9, 12, 32)]);
263	    world2.step({ press: ["c"] }); // c → b lands on tick 21
264	    world2.runTo(5);
265	    world2.step({ press: ["a"] }); // a → b, lands on tick 26
266	    expect(ofKind(world2.runTo(21), "duel-reserved")).toHaveLength(1);
267	    expect(world2.step({ press: ["a"] })).toEqual([]); // already attacking; and b is reserved anyway
268	    expect(ofKind(world2.runTo(26), "attempt-missed")).toEqual([
269	      { kind: "attempt-missed", tick: 26, attackerId: "a", defenderId: "b", reason: "defender-ineligible", cooldownEndTick: 146 },
270	    ]);
271	    // A fresh attacker finds no target among the reserved.
272	    const world3 = new World([ship("a", 3, 12), ship("b", 7, 12), ship("c", 9, 12, 32)]);
273	    world3.step({ press: ["c"] });
274	    world3.runTo(21);
275	    expect(world3.step({ press: ["a"] })).toEqual([]);
276	  });
277	
278	  it("neither lets a respawning loser attack nor be attacked", () => {
279	    const world = new World([ship("a", 5, 12), ship("b", 8, 12)]);
280	    world.set("a", { ready: true });
281	    world.set("b", { ready: true });
282	    grapple(world, "a");
283	    world.runTo(81);
284	    world.step({ reports: [{ kind: "end", duelId: "duel:21:1:a:b", tick: 82, outcome: "win", winner: "a" }] });
285	    world.step({ reports: [{ kind: "settled", duelId: "duel:21:1:a:b", tick: 83 }] });
286	    expect(world.record("b")?.respawn).toMatchObject({ respawnTick: 382 });
287	    world.players.set("c", ship("c", 6, 12));
288	    world.set("b", { heading: 32 });
289	    expect(world.step({ press: ["c", "b"] })).toEqual([]);
290	  });
291	
292	  it("refuses new attempts at the cap of four duels and preempts a hit that would exceed it, without cooldown", () => {
293	    const pairs = [1, 8, 15, 22].flatMap((row, index) => [ship(`p${index}a`, 3, row), ship(`p${index}b`, 5, row)]);
294	    const world = new World([...pairs, ship("x", 30, 12), ship("y", 32, 12)]);
295	    world.step({ press: ["p0a", "p1a", "p2a", "p3a"] });
296	    expect(ofKind(world.runTo(21), "duel-reserved")).toHaveLength(4);
297	    expect(world.step({ press: ["x"] })).toEqual([]);
298	    expect(duelMarkers(world.state)).toHaveLength(4);
299	
300	    // Three duels running, two hits landing together: the nearer takes the last place.
301	    const three = [1, 8, 15].flatMap((row, index) => [ship(`p${index}a`, 3, row), ship(`p${index}b`, 5, row)]);
302	    const race = new World([...three, ship("q", 28, 4), ship("r", 30, 4), ship("s", 28, 16), ship("t", 31, 16)]);
303	    race.step({ press: ["p0a", "p1a", "p2a", "q", "s"] });
304	    const events = race.runTo(21);
305	    expect(ofKind(events, "duel-reserved").map((event) => event.players)).toEqual([
306	      ["p0a", "p0b"],
307	      ["p1a", "p1b"],
308	      ["p2a", "p2b"],
309	      ["q", "r"],
310	    ]);
311	    expect(ofKind(events, "attempt-preempted")).toEqual([{ kind: "attempt-preempted", tick: 21, attackerId: "s", defenderId: "t", reason: "duel-cap" }]);
312	    expect(race.record("s")).toBeUndefined();
313	  });
314	
315	  it("keeps modes apart: a ship never grapples a player on foot, and changing mode during the windup escapes", () => {
316	    const world = new World([ship("a", 5, 12), { ...ship("walker", 6, 12), mode: "foot" }]);
317	    expect(world.step({ press: ["a", "walker"] })).toEqual([]);
318	    const escape = new World([ship("a", 5, 12), ship("b", 7, 12)]);
319	    escape.step({ press: ["a"] });
320	    escape.set("b", { mode: "foot" });
321	    expect(ofKind(escape.runTo(21), "attempt-missed")[0]).toMatchObject({ reason: "defender-ineligible" });
322	  });
323	
324	  it("lets a disconnected defender be attacked (§12) but not a disconnected attacker start", () => {
325	    const world = new World([ship("a", 5, 12), ship("b", 7, 12, 32, { connected: false })]);
326	    expect(world.step({ press: ["b"] })).toEqual([]);
327	    world.step({ press: ["a"] });
328	    expect(ofKind(world.runTo(22), "duel-reserved")).toHaveLength(1);
329	  });
330	
331	  it("cancels an attempt whose attacker leaves the match, with no cooldown", () => {
332	    const world = new World([ship("a", 5, 12), ship("b", 7, 12)]);
333	    world.step({ press: ["a"] });
334	    world.remove("a");
335	    expect(world.step()).toEqual([{ kind: "attempt-cancelled", tick: 2, attackerId: "a", defenderId: "b", reason: "attacker-ineligible" }]);
336	  });
337	});
338	
339	describe("same-tick resolution (§5)", () => {
340	  it("resolves a chain by distance: A→B and B→C on one tick", () => {
341	    const chain = new World([ship("a", 5, 12), ship("b", 7, 12), ship("c", 10, 12)]);
342	    chain.step({ press: ["a", "b"] });
343	    expect(kinds(chain.runTo(21))).toEqual(["duel-reserved", "attempt-preempted"]);
344	    expect(chain.state.duels.map((duel) => duel.players)).toEqual([["a", "b"]]);
345	
346	    const reversed = new World([ship("a", 4, 12), ship("b", 7, 12), ship("c", 9, 12)]);
347	    reversed.step({ press: ["a", "b"] });
348	    const reversedEvents = reversed.runTo(21);
349	    expect(ofKind(reversedEvents, "duel-reserved").map((event) => event.players)).toEqual([["b", "c"]]);
350	    expect(ofKind(reversedEvents, "attempt-preempted")).toEqual([{ kind: "attempt-preempted", tick: 21, attackerId: "a", defenderId: "b", reason: "conflict" }]);
351	  });
352	
353	  it("resolves mutual attacks A→B and B→A to the lower attacker id", () => {
354	    for (const [left, right] of [
355	      ["a", "b"],
356	      ["b", "a"],
357	    ] as const) {
358	      const world = new World([ship(left, 5, 12, 0), ship(right, 7, 12, 32)]);
359	      world.step({ press: [left, right] });
360	      expect(world.state.attempts).toHaveLength(2);
361	      const events = world.runTo(21);
362	      expect(ofKind(events, "duel-reserved")[0]!.players).toEqual(["a", "b"]);
363	      expect(ofKind(events, "attempt-preempted")).toEqual([{ kind: "attempt-preempted", tick: 21, attackerId: "b", defenderId: "a", reason: "conflict" }]);
364	    }
365	  });
366	
367	  it("cancels the pending attempt of a player reserved as a defender", () => {
368	    const world = new World([ship("a", 5, 12, 0), ship("b", 7, 12, 32)]);
369	    world.step({ press: ["a"] });
370	    world.runTo(4);
371	    world.step({ press: ["b"] });
372	    expect(world.runTo(21).filter((event) => event.kind !== "duel-reserved")).toEqual([
373	      { kind: "attempt-cancelled", tick: 21, attackerId: "b", defenderId: "a", reason: "attacker-ineligible" },
374	    ]);
375	  });
376	});
377	
378	describe("reservation and transition", () => {
379	  function reserved(ready: { a: boolean; b: boolean }): World {
380	    const world = new World([ship("a", 5, 12, 0, { ready: ready.a }), ship("b", 8, 12, 0, { ready: ready.b })]);
381	    grapple(world, "a");
382	    expect(world.state.duels[0]).toMatchObject({ id: "duel:21:1:a:b", phase: "transition", reservedTick: 21 });
383	    return world;
384	  }
385	
386	  it("starts the fight once the three-second countdown is over with both clients ready", () => {
387	    const world = reserved({ a: true, b: true });
388	    expect(world.runTo(80)).toEqual([]);
389	    expect(world.step()).toEqual([{ kind: "duel-started", tick: 81, duelId: "duel:21:1:a:b" }]);
390	    expect(world.state.duels[0]).toMatchObject({ phase: "fighting", startTick: 81 });
391	  });
392	
393	  it("waits for a late client and starts when it is ready", () => {
394	    const world = reserved({ a: true, b: false });
395	    world.runTo(120);
396	    world.set("b", { ready: true });
397	    expect(world.step()).toEqual([{ kind: "duel-started", tick: 121, duelId: "duel:21:1:a:b" }]);
398	  });
399	
400	  it("forfeits a client still not ready ten seconds after the reservation, ending the duel in the state", () => {
401	    const world = reserved({ a: true, b: false });
402	    expect(world.runTo(220)).toEqual([]);
403	    expect(world.step()).toEqual([{ kind: "duel-forfeited", tick: 221, duelId: "duel:21:1:a:b", forfeiter: "b", winner: "a" }]);
404	    expect(world.state.duels[0]).toMatchObject({ phase: "ended", end: { tick: 221, outcome: "win", winner: "a", loser: "b", cause: "readiness" } });
405	    // The caller reports only the settlement; a second end is refused and changes nothing.
406	    const before = world.state;
407	    const refused = world.step({ reports: [{ kind: "end", duelId: "duel:21:1:a:b", tick: 222, outcome: "draw" }] });
