1	import { createSeaMap, HEADING_COUNT, isNavigable, seaMap, type SeaMapDefinition } from "@pirate-sea-race/content";
2	import { describe, expect, it } from "vitest";
3	import { nextInt } from "../random.js";
4	import {
5	  bearing,
6	  createEncounterConfig,
7	  createEncounterState,
8	  ENCOUNTER_EVENT_KINDS,
9	  encounterRules,
10	  hashState,
11	  stepEncounters,
12	  tileCentre,
13	  tileOf,
14	  type DuelReport,
15	  type EncounterConfig,
16	  type EncounterEvent,
17	  type EncounterMode,
18	  type EncounterPlayerInput,
19	  type EncounterState,
20	  type EncounterTickInput,
21	} from "./index.js";
22	
23	type Draw = (bound: number) => number;
24	
25	function generator(seed: number): Draw {
26	  let rng = seed;
27	  return (bound) => {
28	    const drawn = nextInt(rng, bound);
29	    rng = drawn.state;
30	    return drawn.value;
31	  };
32	}
33	
34	function shuffled<T>(items: readonly T[], draw: Draw): T[] {
35	  const copy = [...items];
36	  for (let index = copy.length - 1; index > 0; index--) {
37	    const other = draw(index + 1);
38	    [copy[index], copy[other]] = [copy[other]!, copy[index]!];
39	  }
40	  return copy;
41	}
42	
43	/** A small synthetic sea: scattered land and shoals, and a dock on each side. */
44	function syntheticSea(seed: number, size: number): SeaMapDefinition {
45	  const draw = generator(seed);
46	  const rows = Array.from({ length: size }, (_, row) =>
47	    Array.from({ length: size }, (_, column) => {
48	      if ((row === 1 && column === Math.floor(size / 2)) || (row === size - 2 && column === 2) || (column === size - 2 && row === 3)) return "D";
49	      const roll = draw(100);
50	      return roll < 7 ? "#" : roll < 12 ? "%" : ".";
51	    }).join(""),
52	  );
53	  return createSeaMap({ name: `synthetic-${seed}`, widthTiles: size, heightTiles: size, rows, islands: [], spawnSlots: [], hub: { tileX: size >> 1, tileY: size >> 1 } });
54	}
55	
56	interface Scenario {
57	  readonly name: string;
58	  readonly map: SeaMapDefinition;
59	  readonly config: EncounterConfig;
60	  /** Players on foot are allowed (the islands' placeholder rules). */
61	  readonly foot: boolean;
62	  /** Players start within this many tiles of the map's hub. */
63	  readonly spread: number;
64	}
65	
66	const sliceScenario: Scenario = { name: "slice sea", map: seaMap, config: createEncounterConfig(), foot: false, spread: 7 };
67	const smallA = syntheticSea(11, 20);
68	const smallB = syntheticSea(23, 14);
69	const scenarios: readonly Scenario[] = [
70	  sliceScenario,
71	  { name: "synthetic 20×20", map: smallA, config: createEncounterConfig({ map: smallA }), foot: true, spread: 9 },
72	  // A cap of two duels, so a hit meets the cap often.
73	  { name: "synthetic 14×14, cap 2", map: smallB, config: createEncounterConfig({ map: smallB, rules: { ...encounterRules, maxDuels: 2 } }), foot: true, spread: 6 },
74	  { name: "synthetic 20×20, cap 1", map: smallA, config: createEncounterConfig({ map: smallA, rules: { ...encounterRules, maxDuels: 1 } }), foot: false, spread: 5 },
75	];
76	
77	const ID_POOL = ["p1", "p10", "p2", "P3", "a", "B", "crew", "Z9", "m", "q7", "x"];
78	
79	interface DuelPlan {
80	  readonly readyAt: readonly [number | null, number | null];
81	  readonly fightTicks: number;
82	  readonly outcome: "win" | "draw" | "cancelled";
83	  readonly winner: 0 | 1;
84	  readonly settleDelay: number;
85	}
86	
87	interface Run {
88	  readonly spawnProtected: readonly string[];
89	  readonly inputs: readonly EncounterTickInput[];
90	  readonly states: readonly EncounterState[];
91	  readonly hashes: readonly string[];
92	  readonly events: readonly (readonly EncounterEvent[])[];
93	}
94	
95	/**
96	 * A reactive match: players wander (ships over navigable tiles only), turn, press, disconnect, change mode, and
97	 * report objective ends; a duel plan decides each reserved duel's readiness, fight, result and settlement, reported
98	 * as the caller would; returns move the players. Now and then it sends a stray report the rules must refuse.
99	 */
100	function play(scenario: Scenario, seed: number, ticks: number): Run {
101	  const { map, config } = scenario;
102	  const draw = generator(seed);
103	  const chance = (perMille: number) => draw(1000) < perMille;
104	  const count = 4 + draw(ID_POOL.length - 3);
105	  const ids = shuffled(ID_POOL, draw).slice(0, count);
106	  const hub = map.hub;
107	  const navigableNear = (tileX: number, tileY: number, radius: number) => {
108	    for (let attempt = 0; attempt < 200; attempt++) {
109	      const x = tileX + draw(2 * radius + 1) - radius;
110	      const y = tileY + draw(2 * radius + 1) - radius;
111	      if (isNavigable(map, x, y)) return tileCentre(map, { tileX: x, tileY: y });
112	    }
113	    return null;
114	  };
115	  const players = new Map<string, EncounterPlayerInput>();
116	  for (const id of ids) {
117	    const at = navigableNear(hub.tileX, hub.tileY, scenario.spread)!;
118	    players.set(id, { id, mode: "ship", ...at, heading: draw(HEADING_COUNT), connected: true, attack: false, ready: false, protectionEndedBy: null });
119	  }
120	  const matchOverAt = seed % 5 === 0 ? ticks - 30 - draw(200) : -1;
121	  const spawnProtected = ids.filter(() => draw(3) === 0);
122	  let state = createEncounterState(config, { spawnProtected });
123	  const plans = new Map<string, DuelPlan>();
124	  const inputs: EncounterTickInput[] = [];
125	  const states: EncounterState[] = [];
126	  const events: EncounterEvent[][] = [];
127	
128	  for (let tick = 1; tick <= ticks; tick++) {
129	    // Now and then everyone presses at once, so hits land together and conflict.
130	    const volley = chance(25) || (tick >= matchOverAt - 10 && tick < matchOverAt);
131	    const inDuel = new Set(state.duels.flatMap((duel) => duel.players));
132	    const respawning = new Set(state.players.filter((player) => player.respawn !== null).map((player) => player.id));
133	    for (const id of ids) {
134	      let player = { ...players.get(id)!, attack: false, protectionEndedBy: null as EncounterPlayerInput["protectionEndedBy"] };
135	      if (!inDuel.has(id) && !respawning.has(id)) {
136	        if (player.mode === "ship") {
137	          if (chance(500)) {
138	            const x = player.x + draw(97) - 48;
139	            const y = player.y + draw(97) - 48;
140	            const tile = tileOf(map, { x, y });
141	            if (isNavigable(map, tile.tileX, tile.tileY)) player = { ...player, x, y };
142	          }
143	          if (chance(30)) {
144	            const tile = tileOf(map, player);
145	            const jump = navigableNear(tile.tileX, tile.tileY, 3);
146	            if (jump !== null) player = { ...player, ...jump };
147	          }
148	          // Closing in: a jump to within two tiles of someone else.
149	          if (chance(15)) {
150	            const tile = tileOf(map, players.get(ids[draw(ids.length)]!)!);
151	            const jump = navigableNear(tile.tileX, tile.tileY, 2);
152	            if (jump !== null) player = { ...player, ...jump };
153	          }
154	        } else if (chance(500)) {
155	          const limit = map.widthTiles * map.subUnitsPerTile - 1;
156	          player = { ...player, x: Math.min(limit, Math.max(0, player.x + draw(129) - 64)), y: Math.min(limit, Math.max(0, player.y + draw(129) - 64)) };
157	        }
158	        if (chance(200)) player = { ...player, heading: (player.heading + draw(9) - 4 + HEADING_COUNT) % HEADING_COUNT };
159	        // Chasing: turn towards someone, as a player lining up a grapple would.
160	        if (chance(40)) {
161	          const other = players.get(ids[draw(ids.length)]!)!;
162	          player = { ...player, heading: bearing(player, other) ?? player.heading };
163	        }
164	        if (chance(20)) player = { ...player, heading: draw(HEADING_COUNT) };
165	        if (scenario.foot && chance(4)) {
166	          const tile = tileOf(map, player);
167	          const mode: EncounterMode = player.mode === "ship" ? "foot" : "ship";
168	          if (mode === "foot" || isNavigable(map, tile.tileX, tile.tileY)) player = { ...player, mode };
169	        }
170	        if (volley || chance(80)) player = { ...player, attack: true };
171	      }
172	      if (chance(5)) player = { ...player, connected: !player.connected };
173	      if (chance(6)) player = { ...player, protectionEndedBy: draw(2) === 0 ? "claim" : "collection" };
174	      players.set(id, player);
175	    }
176	
177	    // Readiness, results and settlements, as the room and the ledger would report them.
178	    const reports: DuelReport[] = [];
179	    for (const duel of state.duels) {
180	      let plan = plans.get(duel.id);
181	      if (plan === undefined) {
182	        const style = draw(10);
183	        const soon = () => duel.reservedTick + draw(90);
184	        const readyAt: [number | null, number | null] = style < 6 ? [soon(), soon()] : style < 8 ? (draw(2) === 0 ? [soon(), null] : [null, soon()]) : [null, null];
185	        const roll = draw(10);
186	        plan = { readyAt, fightTicks: 20 + draw(200), outcome: roll < 7 ? "win" : roll < 9 ? "draw" : "cancelled", winner: draw(2) as 0 | 1, settleDelay: draw(10) < 7 ? draw(120) : 280 + draw(120) };
187	        plans.set(duel.id, plan);
188	      }
189	      duel.players.forEach((id, index) => {
190	        const readyAt = plan.readyAt[index] ?? null;
191	        players.set(id, { ...players.get(id)!, ready: readyAt !== null && tick >= readyAt });
192	      });
193	      if (duel.phase === "fighting" && tick >= duel.startTick! + plan.fightTicks) {
194	        const at = Math.max(duel.startTick!, tick - draw(2));
195	        reports.push(plan.outcome === "win" ? { kind: "end", duelId: duel.id, tick: at, outcome: "win", winner: duel.players[plan.winner] } : { kind: "end", duelId: duel.id, tick: at, outcome: plan.outcome });
196	      }
