202	      if (chance(2)) reports.push({ kind: "end", duelId: duel.id, tick, outcome: "win", winner: "nobody" });
203	    }
204	    if (chance(3)) reports.push({ kind: "settled", duelId: "ghost", tick });
205	
206	    const input: EncounterTickInput = { tick, players: ids.map((id) => players.get(id)!), reports, matchOver: tick >= matchOverAt && matchOverAt > 0 };
