250	function isProtectedOnTick(state: EncounterState, input: EncounterTickInput, id: string): boolean {
251	  const protection = state.players.find((player) => player.id === id)?.protection ?? null;
252	  const reported = input.players.find((player) => player.id === id)?.protectionEndedBy ?? null;
