335	      ...ENCOUNTER_EVENT_KINDS,
336	      ...["expired", "attack", "claim", "collection"].map((reason) => `protection-ended:${reason}`),
337	      ...["unknown-duel", "already-ended", "not-ended", "invalid"].map((reason) => `report-refused:${reason}`),
338	      ...["attacker-ineligible", "match-over"].map((reason) => `attempt-cancelled:${reason}`),
